<?php
declare(strict_types=1);
$root=dirname(__DIR__);foreach(['Database','Mailer','Identity','Program'] as $class)require_once "$root/app/$class.php";
$cfg=require "$root/config/test.php";if($cfg['db_name']!=='carrousel_cumple_test')exit(2);date_default_timezone_set($cfg['timezone']);$db=Database::connect($cfg);$identity=new Identity($db,$cfg,new Mailer($cfg,fn($m)=>null));$p=new Program($db,$identity);$today=new DateTimeImmutable();
$client=$p->register($identity->user(2),['name'=>'Concurrente '.uniqid(),'day'=>(int)$today->format('d'),'month'=>(int)$today->format('m'),'email'=>'race@example.test','terms_accepted'=>true,'request_id'=>'race-'.uniqid()]);
function race(string $mode,string $code=''):array {global $root;$start=microtime(true)+1;$jobs=[];foreach([2,3] as $user){$pipes=[];$proc=proc_open([PHP_BINARY,"$root/tests/race-worker.php",$mode,(string)$start,$code,(string)$user],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$proc,$pipes];}$results=[];foreach($jobs as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);if($exit!==0)throw new RuntimeException('Worker failed '.$err);$results[]=json_decode($out,true,512,JSON_THROW_ON_ERROR);}return $results;}
race('issue');$q=$db->prepare('SELECT campaign_id,COUNT(*) n FROM coupons WHERE customer_id=? GROUP BY campaign_id');$q->execute([$client['customer']['id']]);foreach($q->fetchAll() as $row)if((int)$row['n']!==1)throw new RuntimeException('Emisión duplicada.');echo "PASS dos procesos: una emisión por cliente/campaña/año\n";
$q=$db->prepare('SELECT code FROM coupons WHERE customer_id=? ORDER BY id LIMIT 1');$q->execute([$client['customer']['id']]);$code=$q->fetchColumn();$results=race('redeem',$code);if(count(array_filter($results,fn($r)=>$r['ok']))!==1)throw new RuntimeException('Canje concurrente inválido.');echo "PASS dos centros: un canje, un rechazo\n";
$p->register($identity->user(2),['name'=>'Correo concurrente '.uniqid(),'day'=>(int)$today->format('d'),'month'=>(int)$today->format('m'),'email'=>'race-mail@example.test','terms_accepted'=>true,'request_id'=>'mail-'.uniqid()]);$p->issue();
file_put_contents("$root/storage/race-mail.log",'');race('send');$ids=file("$root/storage/race-mail.log",FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);if(!$ids||count($ids)!==count(array_unique($ids)))throw new RuntimeException('Correo duplicado o prueba vacía.');echo "PASS dos trabajadores: ningún correo aceptado dos veces\n";
